// ZeroNote 分享插件 —— 构建脚本。
//
// 与 `tauri-plugin-uri-reader` 同构：`tauri_plugin::Builder` 做两件事：
//   ① 按 COMMANDS 在 `permissions/autogenerated/` 生成权限文件；
//   ② `.android_path("android")` 告诉 Tauri CLI 本插件的 Android 模块在哪
//      （CLI 据此重写 `gen/android/tauri.settings.gradle`，不需要手改 gradle）。
const COMMANDS: &[&str] = &["share_text"];

fn main() {
  tauri_plugin::Builder::new(COMMANDS)
    .android_path("android")
    .build();
}
